import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial, Color, DoubleSide } from 'three/webgpu';
import { uv, vec2, mix, step, length, sub, add, mul, divide, fract, floor, max, min, clamp, smoothstep, float, color } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const root = new Group();
  root.userData.handlers = {};

  // Panel (background) ----------------------------------------------------
  const panelWidth = 3.2;
  const panelHeight = 2.2;
  const panelGeom = new PlaneGeometry(panelWidth, panelHeight);
  const panelMat = new MeshBasicNodeMaterial();
  panelMat.transparent = true;
  panelMat.depthWrite = false;

  // Nodes for gradient, border and grid
  const uvNode = uv(); // 0‑1 UV
  const borderWidthWorld = 0.006;
  const borderWidthUV = borderWidthWorld / panelWidth; // ≈0.001875

  const edgeDist = min(min(uvNode.x, sub(1.0, uvNode.x)), min(uvNode.y, sub(1.0, uvNode.y)));
  const borderMask = sub(1.0, step(borderWidthUV, edgeDist)); // 1 inside border

  const centerCol = color('#14141a');
  const edgeCol = color('#0b0b10');
  const radial = length(sub(uvNode, vec2(0.5, 0.5))).div(0.5); // 0‑1 radius
  const gradientCol = mix(centerCol, edgeCol, radial);

  const borderCol = color('#26262f');
  let baseCol = mix(gradientCol, borderCol, borderMask);

  // Grid (0.25‑unit pitch, 6 % opacity)
  const gridPitchWorld = 0.25;
  const gridPitchUV = gridPitchWorld / panelWidth;
  const lineWidthWorld = 0.001;
  const lineWidthUV = lineWidthWorld / panelWidth;
  const gridX = step(lineWidthUV, fract(mul(uvNode.x, float(1.0).div(gridPitchUV))));
  const gridY = step(lineWidthUV, fract(mul(uvNode.y, float(1.0).div(gridPitchUV))));
  const gridMask = max(gridX, gridY);
  const gridCol = color('#e8ecf2');
  const gridOpacity = 0.06;
  baseCol = mix(baseCol, gridCol, mul(gridMask, gridOpacity));

  panelMat.color = baseCol;
  const panelMesh = new Mesh(panelGeom, panelMat);
  root.add(panelMesh);

  // Ghost preview ---------------------------------------------------------
  const ghostGroup = new Group();
  ghostGroup.position.set(-0.5, 0, 0.001);
  root.add(ghostGroup);

  // Wireframe outline
  const outlineGeom = new PlaneGeometry(1.1, 1.4);
  const outlineMat = new MeshBasicNodeMaterial({ color: '#e8ecf2', transparent: true, opacity: 0.3, wireframe: true });
  const outlineMesh = new Mesh(outlineGeom, outlineMat);
  ghostGroup.add(outlineMesh);

  // Ghost dial (circle)
  const dialGeom = new THREE.RingGeometry(0.0, 0.55, 32);
  const dialMat = new MeshBasicNodeMaterial({ color: '#e8ecf2', transparent: true, opacity: 0.3, side: DoubleSide });
  const dialMesh = new Mesh(dialGeom, dialMat);
  dialMesh.position.set(0, 0.3, 0);
  ghostGroup.add(dialMesh);

  // Ghost text bars
  const barGeom = new PlaneGeometry(0.7, 0.06);
  const barMat = new MeshBasicNodeMaterial({ color: '#e8ecf2', transparent: true, opacity: 0.22 });
  const bar1 = new Mesh(barGeom, barMat);
  bar1.position.set(0, -0.2, 0);
  ghostGroup.add(bar1);
  const bar2 = new Mesh(barGeom, barMat);
  bar2.position.set(0, -0.3, 0);
  ghostGroup.add(bar2);

  // Ghost opacity breathing
  const ghostAnim = { opacity: 0.24 };
  const ghostTween = gsap.to(ghostAnim, {
    opacity: 0.34,
    duration: 2.4,
    ease: 'cubic-bezier(0.445,0.05,0.55,0.95)',
    repeat: -1,
    yoyo: true,
    onUpdate: () => {
      ghostGroup.traverse(o => {
        if (o.material && 'opacity' in o.material) o.material.opacity = ghostAnim.opacity;
      });
    }
  });

  // Text column -----------------------------------------------------------
  const textGroup = new Group();
  textGroup.position.set(0.5, 0, 0.001);
  root.add(textGroup);

  const headline = ctx.fontAtlas.createText('Your ledger is empty.', {
    fontSize: 34,
    color: '#16161d',
    align: 'left'
  });
  headline.position.set(0, 0.3, 0);
  textGroup.add(headline);

  const body = ctx.fontAtlas.createText('Commissioned pieces and saved references will appear here once you begin.', {
    fontSize: 13,
    color: '#16161d',
    align: 'left'
  });
  body.position.set(0, 0, 0);
  textGroup.add(body);

  // CTA button ------------------------------------------------------------
  const ctaGroup = new Group();
  ctaGroup.position.set(0, -0.5, 0);
  textGroup.add(ctaGroup);

  const ctaGeom = new PlaneGeometry(1.5, 0.36);
  const ctaMat = new MeshStandardNodeMaterial();
  ctaMat.transparent = true;
  ctaMat.depthWrite = false;

  const ctaUV = uv();
  const gradT = ctaUV.y;
  const gradCol = mix(color('#ff4450'), color('#c1121f'), gradT);
  ctaMat.color = gradCol;
  ctaMat.emissive = color('#ff2a38');
  ctaMat.emissiveIntensity = 1.5;

  const ctaMesh = new Mesh(ctaGeom, ctaMat);
  ctaGroup.add(ctaMesh);

  const ctaLabel = ctx.fontAtlas.createText('BROWSE THE COLLECTION', {
    fontSize: 13,
    color: '#16161d',
    align: 'center'
  });
  ctaLabel.position.set(0, 0, 0.001);
  ctaGroup.add(ctaLabel);

  // CTA press interaction --------------------------------------------------
  ctaGroup.userData.handlers = {
    pointerdown: () => {
      gsap.to(ctaGroup.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)'
      });
    },
    pointerup: () => {
      gsap.to(ctaGroup.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)'
      });
    }
  };

  // Mount fade‑up animation ------------------------------------------------
  const mountAnim = { opacity: 0 };
  const mountTween = gsap.to(mountAnim, {
    opacity: 1,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    onUpdate: () => {
      root.traverse(o => {
        if (o.material && 'opacity' in o.material) o.material.opacity = mountAnim.opacity;
      });
    }
  });
  gsap.from(root.position, {
    y: 0.2,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
  });

  // Cleanup ---------------------------------------------------------------
  const timelines = [ghostTween, mountTween];
  root.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    root.traverse(o => {
      if (o.geometry) o.geometry.dispose();
      if (o.material) {
        if (o.material.map) o.material.map.dispose();
        o.material.dispose();
      }
    });
  };

  return root;
}
